svg.script:
(function(){
  var root=document.getElementById('rootSvg');
  var status=document.getElementById('statusText');
  var paused=false;
  function show(){ if(status) status.textContent=paused?'paused':'playing'; }
  function doPause(){ try{ if(root.pauseAnimations) root.pauseAnimations(); }catch(e){} paused=true; show(); }
  function doPlay(){ try{ if(root.unpauseAnimations) root.unpauseAnimations(); }catch(e){} paused=false; show(); }
  function toggle(){ paused?doPlay():doPause(); }
  var pb=document.getElementById('pauseBtn'), qb=document.getElementById('playBtn');
  if(pb){ pb.addEventListener('click',doPause); pb.addEventListener('keydown',function(e){ if(e.key==='Enter'||e.key===' '){e.preventDefault();doPause();} }); }
  if(qb){ qb.addEventListener('click',doPlay); qb.addEventListener('keydown',function(e){ if(e.key==='Enter'||e.key===' '){e.preventDefault();doPlay();} }); }
  document.addEventListener('keydown',function(e){ if(e.key===' '||e.key==='p'||e.key==='P'){e.preventDefault();toggle();} });
  show();
})();
